class Solution {
    public void solve(char[][] board) {
        int rows = board.length;
        int cols = board[0].length;

        for (int r = 0; r < rows; r++) {
            markBorder(board, r, 0);
            markBorder(board, r, cols - 1);
        }
        for (int c = 0; c < cols; c++) {
            markBorder(board, 0, c);
            markBorder(board, rows - 1, c);
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == 'O') {
                    board[r][c] = 'X';
                } else if (board[r][c] == '#') {
                    board[r][c] = 'O';
                }
            }
        }
    }

    private void markBorder(char[][] board, int row, int col) {
        if (row < 0 || row >= board.length || col < 0 || col >= board[0].length || board[row][col] != 'O') {
            return;
        }
        board[row][col] = '#';
        markBorder(board, row + 1, col);
        markBorder(board, row - 1, col);
        markBorder(board, row, col + 1);
        markBorder(board, row, col - 1);
    }
}

import java.util.*;

class Solution {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public void solve(char[][] board) {
        int rows = board.length;
        int cols = board[0].length;
        Queue<int[]> queue = new ArrayDeque<>();

        for (int r = 0; r < rows; r++) {
            enqueueIfOpen(board, queue, r, 0);
            enqueueIfOpen(board, queue, r, cols - 1);
        }
        for (int c = 0; c < cols; c++) {
            enqueueIfOpen(board, queue, 0, c);
            enqueueIfOpen(board, queue, rows - 1, c);
        }

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            for (int[] direction : DIRECTIONS) {
                int nextRow = cell[0] + direction[0];
                int nextCol = cell[1] + direction[1];
                if (nextRow >= 0 && nextRow < rows && nextCol >= 0 && nextCol < cols
                        && board[nextRow][nextCol] == 'O') {
                    board[nextRow][nextCol] = '#';
                    queue.offer(new int[]{nextRow, nextCol});
                }
            }
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == 'O') {
                    board[r][c] = 'X';
                } else if (board[r][c] == '#') {
                    board[r][c] = 'O';
                }
            }
        }
    }

    private void enqueueIfOpen(char[][] board, Queue<int[]> queue, int row, int col) {
        if (board[row][col] == 'O') {
            board[row][col] = '#';
            queue.offer(new int[]{row, col});
        }
    }
}

class Solution {
    public void solve(char[][] board) {
        int rows = board.length;
        int cols = board[0].length;
        int sentinel = rows * cols;
        UnionFind uf = new UnionFind(sentinel + 1);
        int[][] directions = {{1, 0}, {0, 1}};

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (board[row][col] != 'O') {
                    continue;
                }
                int id = row * cols + col;
                if (row == 0 || col == 0 || row == rows - 1 || col == cols - 1) {
                    uf.union(id, sentinel);
                }
                for (int[] direction : directions) {
                    int nextRow = row + direction[0];
                    int nextCol = col + direction[1];
                    if (nextRow < rows && nextCol < cols && board[nextRow][nextCol] == 'O') {
                        uf.union(id, nextRow * cols + nextCol);
                    }
                }
            }
        }

        int safe = uf.find(sentinel);
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (board[row][col] == 'O' && uf.find(row * cols + col) != safe) {
                    board[row][col] = 'X';
                }
            }
        }
    }

    static class UnionFind {
        int[] parent;
        int[] rank;

        UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return;
            }
            if (rank[rootA] < rank[rootB]) {
                parent[rootA] = rootB;
            } else if (rank[rootA] > rank[rootB]) {
                parent[rootB] = rootA;
            } else {
                parent[rootB] = rootA;
                rank[rootA]++;
            }
        }
    }
}

import java.util.*;

class Solution {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public void solve(char[][] board) {
        int rows = board.length;
        int cols = board[0].length;
        boolean[][] visited = new boolean[rows][cols];

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (board[row][col] == 'O' && !visited[row][col]) {
                    scanComponent(board, visited, row, col);
                }
            }
        }
    }

    private void scanComponent(char[][] board, boolean[][] visited, int startRow, int startCol) {
        int rows = board.length;
        int cols = board[0].length;
        Queue<int[]> queue = new ArrayDeque<>();
        List<int[]> component = new ArrayList<>();
        boolean touchesBorder = false;

        visited[startRow][startCol] = true;
        queue.offer(new int[]{startRow, startCol});

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            component.add(cell);
            int row = cell[0];
            int col = cell[1];
            if (row == 0 || col == 0 || row == rows - 1 || col == cols - 1) {
                touchesBorder = true;
            }
            for (int[] direction : DIRECTIONS) {
                int nextRow = row + direction[0];
                int nextCol = col + direction[1];
                if (nextRow >= 0 && nextRow < rows && nextCol >= 0 && nextCol < cols
                        && board[nextRow][nextCol] == 'O' && !visited[nextRow][nextCol]) {
                    visited[nextRow][nextCol] = true;
                    queue.offer(new int[]{nextRow, nextCol});
                }
            }
        }

        if (!touchesBorder) {
            for (int[] cell : component) {
                board[cell[0]][cell[1]] = 'X';
            }
        }
    }
}
